async def ensure_module(client):
    modules=await common.paged(client,f"/courses/{COURSE_ID}/modules"); found=next((m for m in modules if m["name"]==MODULE_NAME),None); data={"module[published]":"false"}
    if found:return await common.api(client,"PUT",f"/courses/{COURSE_ID}/modules/{found['id']}",data=data)
    data["module[name]"]=MODULE_NAME; return await common.api(client,"POST",f"/courses/{COURSE_ID}/modules",data=data)

QUESTIONS=[
("Q1 - wage label","What does $56,320 mean in the fixed Sales Agent evidence?","May 2024 U.S. median annual wage from BLS",["DFW starting salary","Guaranteed self-employed income","Typical commission on one home"],"Correct. Keep date, geography, measure, occupation, and source.","The figure is not local, starting, guaranteed, or per-sale pay."),
("Q2 - openings","Why can 3% growth appear beside about 46,300 annual openings?","Many openings replace workers who transfer or leave, while growth measures net employment change.",["Every opening is a new DFW job.","The two figures contradict each other.","Openings are current job postings."],"Correct. Growth and openings measure different things.","Annual openings include replacement needs and are not live postings."),
("Q3 - self employed","What limitation belongs with the BLS wage evidence?","The wage survey excludes self-employed workers even though BLS lists 54% self-employed in each occupation's employer distribution.",["All self-employed income is included.","Self-employment guarantees flexible hours and high pay.","The 54% is a commission rate."],"Correct. Keep employment distribution separate from wage coverage.","Do not mix a worker-distribution fact with the wage survey population."),
("Q4 - TREC route","What is required for a Texas Sales Agent to move from inactive to active status and practice?","Sponsorship by a licensed broker",["A property-appraiser credential","A guaranteed MacArthur placement","One H&L favorite"],"Correct. Sales Agents act on behalf of a sponsoring broker.","The current TREC route requires broker sponsorship for active practice."),
("Q5 - commission boundary","A classroom scenario uses a supplied percentage and split. What can the result prove?","The arithmetic under those fictional supplied conditions",["The standard commission for Texas","Guaranteed take-home pay","Every brokerage agreement"],"Correct. The math is useful when the assumptions remain visible.","Real agreements, splits, expenses, taxes, timing, and closing conditions vary."),]

async def upsert_quiz(client):
    qs=await common.paged(client,f"/courses/{COURSE_ID}/quizzes"); found=next((q for q in qs if q.get("title")==TITLES[4]),None)
    data={"quiz[title]":TITLES[4],"quiz[description]":"<p>Ungraded, unlimited-retry practice on labor, license, and commission labels.</p>","quiz[quiz_type]":"practice_quiz","quiz[published]":"false","quiz[allowed_attempts]":"-1","quiz[show_correct_answers]":"true","quiz[shuffle_answers]":"false"}
    quiz=await common.api(client,"PUT" if found else "POST",f"/courses/{COURSE_ID}/quizzes/{found['id']}" if found else f"/courses/{COURSE_ID}/quizzes",data=data)
    existing=await common.paged(client,f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions")
    for pos,(name,prompt,correct,wrong,yes,no) in enumerate(QUESTIONS,1):
        old=next((q for q in existing if q.get("question_name")==name),None); payload={"question":{"question_name":name,"question_text":prompt,"question_type":"multiple_choice_question","position":pos,"points_possible":1,"correct_comments":yes,"incorrect_comments":no,"answers":[{"answer_text":correct,"answer_weight":100}]+[{"answer_text":x,"answer_weight":0} for x in wrong]}}
        path=f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions/{old['id']}" if old else f"/courses/{COURSE_ID}/quizzes/{quiz['id']}/questions"; await common.api(client,"PUT" if old else "POST",path,json=payload)
    return await common.api(client,"GET",f"/courses/{COURSE_ID}/quizzes/{quiz['id']}")

