def teacher_content(f):
    link,flow=common.file_link,common.flow; c="#5a2d91"
    base={
1:("Four Real-Estate Careers and Boundaries","d(1)(C), d(2)(A)","Keep Sales Agent, Broker, Appraiser/Assessor, and Property Manager boundaries separate.","CAREERS","Four fixed role records and a two-role decision.","Sales Agents need broker sponsorship for active practice; appraiser credentials are separate; property-manager license need depends on duties."),
2:("TREC Route and Variable-Income Math","d(2)(A)","All percentages and splits are fictional classroom conditions. Gross is not take-home.","TREC","Current route sequence and three visible calculations.","Scenario answers: A $5,600 then $3,640; B $9,562.50 then $5,259.38; C $10,500 then $7,350. Accept rounding to cents."),
3:("Flip This House: ROI and Entrepreneurship","d(3)(I)","Workbook estimates are not bids, appraisals, financial advice, or a promise of profit.","FLIP","ROI plan and individual opportunity/responsibility reasoning.","Net changes: kitchen +5,000; bath +2,000; open plan +2,000; patio +2,000; landscaping +1,000; closet -2,000; lighting +500; smart tech -3,000. Multiple plans can earn full credit."),
4:("Real-Estate Labor Evidence","d(5)(A)","Use dated national evidence; do not call it DFW starting pay, current postings, or a shortage.","LABOR","Wage/trend/limit analysis and retryable Quiz.","Brokers $72,280; agents $56,320; difference $15,960; combined 3% growth and 46,300 annual openings. Wage data exclude self-employed workers."),
5:("Private Evidence Brief and Reflection","d(1)(C), d(2)(A), d(3)(I), d(4)(C) support, d(5)(A), d(5)(D) reassessment","Recovery or replacement evidence only; the 5SW map already contains three minors and two majors. Written-only work is not automatically oral evidence.","BRIEF","Private oral evidence brief plus written six-week reflection.","Require two source-labeled facts, correct boundary, tradeoff/limit, next action, and specific six-week reflection. Do not score preference, family finances, accent, confidence, or mode.")}
    out={}
    for d,(title,teks,alert,key,evidence,monitor) in base.items():
        out[d]={"TITLE":title,"SUBTITLE":f"50 minutes · TEKS {teks}","ALERT":f"<strong>Accuracy boundary:</strong> {alert}","PREP":f'<ul><li>Post {link(f[key]["id"],"the student packet")} and the day interaction.</li><li>Open the matching student guide.</li><li>Keep required evidence fixed and private.</li></ul>',"EVIDENCE":f"<p>{evidence}</p>","FLOW":flow(c,"Warm-up · 5","Activate the decision boundary.")+flow("#4c8b38","Model/read · 10","One accurate example.")+flow("#1f617a","Build evidence · 20","Independent fixed-source work.")+flow("#d39b22","Apply/revise · 10","Tradeoff and limitation.")+flow(c,"Exit · 5","One conclusion and boundary."),"MONITOR":f"<p>{monitor}</p>","RESOURCES":'<p><a href="https://www.trec.texas.gov/become-licensed/sales-agent">TREC Sales Agent</a> · <a href="https://www.trec.texas.gov/public/consumer-information">TREC Consumer Guide</a> · <a href="https://www.bls.gov/ooh/sales/real-estate-brokers-and-sales-agents.htm">BLS Real Estate</a> · <a href="https://www.irvingisd.net/departments-services/career-and-technical-education-cte/high-school-cte/macarthur-high-school">Irving MacArthur CTE</a>.</p>',"SUPPORT":"<p>Short fields hold labels/numbers only; multi-sentence jobs have full-width response blocks. Accept typing, dictation, annotation, enlarged print, bilingual labels, and AAC as appropriate.</p>","FALLBACK":"<p>Fixed packets and embedded visuals are the complete absence/platform route. No personal application, financial disclosure, public posting, H&amp;L, or repeated Xello task.</p>"}
    return out

async def main():
    token=sys.stdin.readline().strip()
    if not token: raise SystemExit("Canvas token required on stdin")
    async with httpx.AsyncClient(headers={"Authorization":f"Bearer {token}"},timeout=120) as client:
        module=await ensure_module(client); path="course files/CCR Materials/5SW/Wk6"; folder=await common.ensure_folder(client,path)
        names={"CAREERS":"5sw-wk6-real-estate-career-boundaries.pdf","TREC":"5sw-wk6-trec-and-variable-income.pdf","FLIP":"5sw-wk6-flip-this-house-evidence-plan.pdf","LABOR":"5sw-wk6-real-estate-labor-evidence.pdf","BRIEF":"5sw-wk6-six-weeks-evidence-brief.pdf","RUBRIC":"5sw-wk6-evidence-brief-rubric.pdf"}
        files={k:await common.upload(client,ROOT/"docs/resources/worksheets"/n,path) for k,n in names.items()}
        vp="course files/CCR Materials/5SW/Wk6/Locked Licensed Visuals"; await common.ensure_folder(client,vp); visuals={"need":await common.upload(client,ASSETS/"day3"/"fyf-p238-flip.jpg",vp),"choices":await common.upload(client,ASSETS/"day3"/"fyf-p239-flip.jpg",vp),"sell":await common.upload(client,ASSETS/"day3"/"fyf-p240-flip.jpg",vp)}
        quiz=await upsert_quiz(client); assignments={}
        for d,key in {1:"CAREERS",2:"TREC",3:"FLIP"}.items(): assignments[d]=await common.upsert_assignment(client,TITLES[d],"<p>Complete privately by annotation, upload, typed labeled responses, or paper.</p>",["student_annotation","online_upload","online_text_entry"],files[key]["id"])
        assignments[5]=await common.upsert_assignment(client,TITLES[5],"<p>Submit a private live/conference/audio/recorded/AAC brief plus written reflection. Keep unpublished and ungraded until the 40/60 map is verified.</p>",["online_upload","online_text_entry","media_recording"],files["BRIEF"]["id"])
        urls={d:f"/courses/{COURSE_ID}/assignments/{a['id']}" for d,a in assignments.items()}; urls[4]=f"/courses/{COURSE_ID}/quizzes/{quiz['id']}"
        s,t=student_content(files,visuals,urls),teacher_content(files); names2={1:"Four Real-Estate Careers and Boundaries",2:"TREC Route and Variable-Income Math",3:"Flip This House: ROI and Entrepreneurship",4:"Real-Estate Labor Evidence",5:"Private Evidence Brief and Reflection"}; interactions={1:("Assignment",assignments[1]["id"],TITLES[1]),2:("Assignment",assignments[2]["id"],TITLES[2]),3:("Assignment",assignments[3]["id"],TITLES[3]),4:("Quiz",quiz["id"],TITLES[4]),5:("Assignment",assignments[5]["id"],TITLES[5])}; order=[]; pages={}
        for d in range(1,6):
            ht=f"Day {d} · {names2[d]}"; h=await prior.upsert_item(client,module["id"],"SubHeader",None,ht); order.append(("SubHeader",h["id"],ht)); st=f"STUDENT: 5SW Wk6 Day {d} - {names2[d]}"; sp=await common.upsert_page(client,st,common.render("5sw-wk6-student.html",{"COURSE_ID":COURSE_ID,"DAY":d,**s[d]})); tt=f"TEACHER: 5SW Wk6 Day {d} Facilitator Guide"; tp=await common.upsert_page(client,tt,common.render("5sw-wk6-teacher.html",{"COURSE_ID":COURSE_ID,"DAY":d,"STUDENT_PAGE_URL":sp["url"],**t[d]})); await prior.upsert_item(client,module["id"],"Page",tp["url"],tt); await prior.upsert_item(client,module["id"],"Page",sp["url"],st); kind,key,title=interactions[d]; await prior.upsert_item(client,module["id"],kind,key,title); order += [("Page",tp["url"],tt),("Page",sp["url"],st),(kind,key,title)]; pages[d]={"teacher":tp,"student":sp}
        items=await common.paged(client,f"/courses/{COURSE_ID}/modules/{module['id']}/items")
        for pos,(kind,key,title) in enumerate(order,1):
            item=next(i for i in items if (kind=="SubHeader" and i.get("id")==key) or (kind=="Page" and i.get("page_url")==key) or (kind in ("Assignment","Quiz") and i.get("content_id")==key)); await common.api(client,"PUT",f"/courses/{COURSE_ID}/modules/{module['id']}/items/{item['id']}",data={"module_item[position]":pos,"module_item[title]":title})
        final=await common.paged(client,f"/courses/{COURSE_ID}/modules/{module['id']}/items"); module=await common.api(client,"GET",f"/courses/{COURSE_ID}/modules/{module['id']}"); print(json.dumps({"module":{"id":module["id"],"published":module["published"]},"folder":{"id":folder["id"],"locked":folder["locked"]},"files":{k:x["id"] for k,x in files.items()},"visuals":{k:x["id"] for k,x in visuals.items()},"quiz":{"id":quiz["id"],"published":quiz.get("published")},"assignments":{str(k):{"id":x["id"],"published":x.get("published")} for k,x in assignments.items()},"pages":{str(d):{k:{"url":x["url"],"published":x["published"]} for k,x in p.items()} for d,p in pages.items()},"items":[{"position":i["position"],"type":i["type"],"title":i["title"]} for i in final]},indent=2))

if __name__=="__main__": asyncio.run(main())
